/**
 * mapSheet.ts: the words of the Light and Dark contour map sheet in each
 * export language.
 *
 * One row per phrase: English, Spanish (Mexico), Portuguese (Brazil), French,
 * German. English is the source, and a row with a language missing fails the
 * build. The sentences other modules write (the provenance, the evidence
 * lines, a measurement's figure and support) are matched to their English row
 * as the sheet is drawn; a test draws every state of the sheet, and runs the
 * modules that write those sentences, and fails on one with no row.
 *
 * Parameters: `{n}` is a figure, rewritten in the number style; `{t_x}` is a
 * phrase with a row of its own; `{u_x}` is copied exactly (a name, a code, a
 * time, text the user typed, or a phrase already in the export language).
 *
 * Drafts until a geomatics reviewer signs them off (`reviewed` in
 * languages.ts); until then every sheet says so under its footer.
 */
import { SUPPORT_CAPTION_TEXT } from './supportCaptions';

